func:
// Execute some task on boot

// First announce we boot, (stop scene)
if (msg.payload === true) {
    global.set('boot', true);
}

// Annonce to stop activity
global.set('stop', true);

// Check persistent autologin
global.set('autologin', (global.get('autologin', 'file') || false), 'file');

// Memory source and destination
const places = ['file', 'default'];
const place = msg.payload === true ? places : [places[1], places[0]];

node.status({text: place[0] + ' to ' + place[1]});

// Memories to manage
const persistent = {
    'auth': { },
    'mqtt': { },
    'room': { },
    'source': { },
    'parent': { },
    'discovery': { },
    'entity': { },
    'block': { },
    'calendar': { },
    'energy': { },
    'scene': { },
    'dknr': { }
}

// Copy backup or at least init
for (const key in persistent) {
    let src = global.get(key, place[0]);
    if (typeof src !== 'object') {
        src = persistent[key];
    }
    global.set(key, src, place[1]);
}

// Stop here on backup process
if (msg.payload === false) {

    // Annonce to stop activity
    global.set('stop', false);

    return;
}

// Check initial memories
const room = global.get('room'); //autoupdate
if (typeof room.base !== 'object') {
    room.base = {};
}
if (typeof room.base.home !== 'object') {
    room.base.home = {
        'id': 'home',
        'name': '> Home',
        'outdoor': 0
    };
}
if (typeof room.base.system !== 'object') {
    room.base.system = {
        'id': 'system',
        'name': '> System',
        'outdoor': 0
    };
}

// Reset non persistent memories
const versatile = {
    'auth': {},
    'browser': {},
    'describe': {
        'app': {
            'project': '',
            'title': '',
            'version': '',
            'mdi': '',
            'login': false // auto login 
        },
        'hmi': {
            'id': '',
            'login': '',
            'level': 'visitor',
            'lang': 'en',
            'page': 'ui - page - auth',
            'room': '',
            'time': 0
        },
        'template': {
            'hmi': {
                'id': '',
                'login': '',
                'level': 'visitor',
                'lang': 'en',
                'page': 'ui - page - auth',
                'room': '',
                'time': 0
            },
            'room': {
                'id': '',
                'name': '',
                'outdoor': 0
            },
            'parent': {
                'id': '',
                'name': '',
                'seen': 0
            },
            'source': {
                'title': '',
                'version': '',
                'git': '',
                'mdi': ''
            },
            'discovery': {
                'name': '',
                'group': '',
                'type': '',
                'unit': '',
                'value': 0,
                'options': {}
            },
            'entity': {
                'uid': '',
                'source': '',
                'id': '',
                'name': '',
                'parent': '',
                'value': '',
                'group': '',
                'room': '',
                'element': '',
                'unit': '',
                'seen': 0,
                'enabled': 0,
                'hidden': 1,
                'options': { }
            },
            'scene': {
                'target': '',
                'enabled': 0,
                'on': 1,
                'off': 0,
                'motion': 0,
                'aperture': 0,
                'nocturnal': 0,
                'diurnal': 0,
                'confort': 0,
                'eco': 0,
                'nightlight': 0,
                'retention': 0,
                'duration': 60, //minutes
                'high': '70',
                'low': '30',
                'illuminance': 0, //2000
                'darkness': 0, //200
                'humidity': 0,
                'daily': 0,
                'openwork': 0,
                'tariff': 0, // limit to a given tariff (see energy preferred tariff)
                'power': 0, // to check if target is really off
                'timer': 0, // for duration routine
                'today': 0, // for daily routine, 1=executed today else 0

                'temperature_setpoint_eco': 19,
                'temperature_setpoint_confort': 21,
                'temperature_setpoint_cold': 18,
                'temperature_coefficient_indoor': 100,
                'temperature_coefficient_outdoor': 10,
                'temperature_duration_aperture': 5,
                'temperature_duration_preheat': 10,
                'temperature_duration_cycle': 60,
                'temperature_duration_offloading': 60,
                'temperature_power_consumption': 1000,
                'temperature_energy_free': 0,

                'temperature_aperture_opened': 0,
                'temperature_aperture_timer': 0,
                'temperature_pilot_state': 'stopped',
                'temperature_pilot_last': 0
            },
            'trigger': {
                'inputhigh': 1, // Minimal input level for high level
                'inputlow': 0, // Maximal input level for low high level
                'outputhigh': 'high', // Output level on high input level. [none,high,low,toggle]
                'outputlow': 'low' // output level for low input level [none, high, low, toggle]
            },
            'routine': {
                'topic': '',
                'payload': false,
                'replay': false,
                'rsp': true,
                'iam': false,
                'scene': {},
                'param': {},
                'trigger': {},
                'target': {},
                'routines': []
            }
        },
        // Enumerators by source and entity id (see common - dknr)
        'enum': { },
        // Binary element with revert value
        'reverts': [],//['aperture', 'door', 'window', 'lock'],
        // Non numeric units
        'texts': ['', 'chex', 'enum', 'text', 'time'],
        // Elements icons
        'elements': {
            'switch': ['toggle-switch-off-outline', 'toggle-switch-outline', 'Switch'],
            'plug': ['power-plug-off', 'power-plug', 'Plug'],
            'power': ['flash-outline', 'flash', 'Power'],
            'current': ['current-ac', 'current-ac', 'Current'],
            'frequency': ['sine-wave', 'sine-wave', 'Frequency'],
            'voltage': ['current-dc', 'current-dc', 'Frequency'],
            'energy': ['meter-electric-outline', 'meter-electric', 'Energy'],
            'light': ['lightbulb-off', 'lightbulb', 'Light'],
            'remote': ['remote-off', 'remote', 'Remote'],
            'door': ['door-closed', 'door-open', 'Door'], // 0=open
            'window': ['window-closed-variant', 'window-open-variant', 'Window'], //0=open
            'lock': ['lock-off', 'lock', 'Lock'], //0=open
            'shutter': ['window-shutter', 'window-shutter-open', 'Shutter'],
            'slider': ['door-sliding', 'door-sliding-open', 'Slider'],
            'waterboiler': ['water-boiler-off', 'water-boiler', 'Waterboiler'],
            'alert': ['bell-off', 'bell', 'Alert'],
            'sound': ['volume-off', 'volume-high', 'Sound'],
            'motion': ['motion-sensor-off', 'motion-sensor', 'Motion'],
            'temperature': ['thermometer-off', 'thermometer', 'Temperature'],
            'humidity': ['water-percent-alert', 'water-percent', 'Humidity'],
            'illuminance': ['sun-wireless-outline', 'sun-wireless', 'Illuminance'],
            'pressure': ['gauge', 'gauge', 'Pressure'],
            'fan': ['fan-off', 'fan', 'Fan'],
            'direction': ['swap-horizontal', 'swap-horizontal-bold', 'Direction'],
            'time': ['clock-outline', 'clock', 'Time'],
            'battery': ['battery-low', 'battery', 'Battery'],
            'mode': ['home-switch-outline', 'home-switch', 'Mode'],
            'text': ['clipboard-text-off', 'clipboard-text', 'Text'],
            'location': ['map-marker-off-outline', 'map-marker', 'Location'],
            'color': ['palette', 'palette', 'Color'],
            'tariff': ['currency-eur-off', 'currency-eur', 'Tariff']
        },
        // Calendar event type
        'calendar': {
            'birthday': [ 'cake-variant-outline', 'cake-variant' ],
            'rendezvous': [ 'alarm-off', 'alarm' ],
            'trashbin': [ 'trash-can-outline', 'trash-can' ],
            'recyclebin': [ 'recycle-vairant', 'recycle' ]
        },
        // Scene elements fields
        'scenes': {
            'humidity': ['enabled', 'on', 'off', 'duration', 'humidity'],
            'light': ['enabled', 'on', 'off', 'high', 'low', 'motion', 'retention', 'duration', 'diurnal', 'nocturnal', 'nightlight', 'illuminance', 'darkness'],
            'shutter': ['enabled', 'on', 'off', 'aperture', 'diurnal', 'nocturnal', 'illuminance', 'darkness', 'openwork', 'daily'],
            'lock': ['enabled', 'on', 'off', 'aperture', 'diurnal', 'nocturnal', 'confort', 'eco'],
            'waterboiler': ['enabled', 'on', 'off', 'duration', 'power', 'tariff', 'daily'],
            'temperature': [
                'enabled',
                'on',
                'off',
                'temperature_setpoint_eco',
                'temperature_setpoint_confort',
                'temperature_setpoint_cold',
                'temperature_coefficient_indoor',
                'temperature_coefficient_outdoor',
                'temperature_duration_aperture',
                'temperature_duration_preheat',
                'temperature_duration_cycle',
                'temperature_duration_offloading',
                'temperature_power_consumption',
                'temperature_energy_free'
            ]
        },
        // Scene routines fields
        'routines': {
            'motion': ['motion-sensor-off', 'motion-sensor'],
            'aperture': ['door-closed', 'door-open'],
            'nocturnal': ['shield-moon-outline', 'shield-moon'],
            'diurnal': ['shield-sun-outline', 'shield-sun'],
            'confort': ['sofa-single', 'sofa-single-outline'],
            'eco': ['sprout-outline', 'sprout'],
            'nightlight': ['lightbulb-night-outline', 'lightbulb-night'],
            'retention': ['timeline-clock-outline', 'timeline-clock'],
            'daily': ['calendar-remove', 'calendar-check'],
            'openwork': ['storefront-remove-outline', 'storefront-check'],
            'duration': ['timer-remove-outline', 'timer-check'],
            'illuminance': ['sun-wireless-outline', 'sun-wireless'],
            'darkness': ['brightness-5', 'brightness-4'],
            'humidity': ['water-percent-alert', 'water-percent'],
            'temperature_energy_free': ['lightning-bolt-outline', 'lightning-bolt']
        },
        'color': {
            'on': '#008000',
            'off': '#FF0000',
            'median': '#F08000',
            'none': '#808000',
            'theme': '#0094CE',
            'empty': '#CCCCCC'
        },
        'page': {

        }
    },
    'dictionary': {},
    'form': {},
    'user': {}
};
for (const key in versatile) {
    global.set(key, versatile[key]);
}

// Register page and more
node.send([msg, null]);

// Wait registrations
await new Promise(resolve => setTimeout(resolve, 1000));

// Continue boot
return [null, msg];

// Maintenance for memory var

// Annonce to stop activity
global.set('stop', true);

// Get memories
let calendar = global.get('calendar'); // autoupdate
let entity = global.get('entity'); // read
let scene = global.get('scene'); // autoupdate
const template = global.get('describe.template') || {}; // read

// Clean up scenes
for (const e in scene) {
    let clean = { };

    const type = (entity[e] || {})['element'] || '';
    if (type === '') {

        continue;
    }
    const fields = global.get('describe["scenes"]["' + type + '"]') || [];
    if (fields.length === 0) {

        continue;
    }

    for (const field in template.scene) {
        if (fields.includes(field)) {
            clean[field] = scene[e][field] || template['scene'][field];
        }
        else {
            clean[field] = template['scene'][field];
        }
    }

    clean['target'] = e;
    clean['trigger'] = scene[e]['trigger'] || { };
    clean['today'] = scene[e]['today'] || 0;
    clean['timer'] = scene[e]['timer'] || 0;

    clean['temperature_aperture_opened'] = scene[e]['temperature_aperture_opened'] || 0;
    clean['temperature_aperture_timer'] = scene[e]['temperature_aperture_timer'] || 0;
    clean['temperature_pilot_state'] = scene[e]['temperature_pilot_state'] || 'stopped';
    clean['temperature_pilot_last'] = scene[e]['temperature_pilot_last'] || 0;

    scene[e] = clean;
}

// Delete perempted calendar entries
const now = new Date();
for (const id in calendar) {
    if (calendar[id]['perempted'] === true) {
        let dt  = new Date(calendar[id]['ts']);
        if (dt < now) {
            delete calendar[id];
        }
    }
}

// Announce to resume activity
global.set('stop', false);

return msg;

// Add page definition to memory

if (typeof msg.payload === 'object'
    && typeof msg.payload.flow === 'string' && msg.payload.flow !== ''
    && typeof msg.payload.id === 'string' && msg.payload.id !== ''
    && typeof msg.payload.icon === 'string' && msg.payload.icon !== ''
    && typeof msg.payload.level === 'object'
) {
    let describe = global.get('describe'); // autoupdate
    describe.page[msg.payload.flow] = msg.payload;
}

msg.payload = '';

return msg;

if (typeof msg.payload === 'object'
    && typeof msg.payload.flow === 'string' && msg.payload.flow !== ''
) {
    let dictionary = global.get('dictionary'); // autoupdate

    for (const lang in msg.payload) {
        if (lang === 'flow' || typeof msg.payload[lang] !== 'object') {

            continue;
        }

        if (typeof dictionary[lang] !== 'object') {
            dictionary[lang] = {};
        }
        if (typeof dictionary[lang][msg.payload.flow] !== 'object') {
            dictionary[lang][msg.payload.flow] = {};
        }
        dictionary[lang][msg.payload.flow] = { ...dictionary[lang][msg.payload.flow], ...msg.payload[lang] };
    }
}

msg.payload = '';

return msg;

// Prepare project query
if (typeof msg.payload.activeProject === 'string') {
    return {
        'topic': '',
        'payload': '',
        'filename': '/data/projects/' + msg.payload.activeProject + '/package.json'
    };
}

return;

delete msg.filename;

// Get memories
let describe = global.get('describe'); // autoupdate

if (typeof msg.payload === 'object') {
    describe.app = {
        'project': msg.payload.name,
        'title': msg.payload.description.slice(5),
        'version' : msg.payload.version,
        'icon': 'alpha-d',
        'login': !!describe.app.login
    };
}

// Set a default empty hmi user
msg.hmi = describe.template.hmi;

msg.payload = '';

// Get UI user
msg = await node.linkcall('common - ui - hmi', msg);

// Set notice
msg.notice = msg.dictionary.notice.boot_success || 'Successfully started';
msg = await node.linkcall('common - ui - notice', msg);

// Wait memories
msg = await node.linkcall('common - wait', msg);

// Annonce to resume activity
global.set('stop', false);

return msg;

if (typeof msg.notice === 'string' && msg.notice !== '') {
    let temp = msg.payload;
    msg.payload = msg.notice;

    node.send([null, msg]);

    msg.payload = temp;
}

return [msg, null];

// Get memories
let form = global.get('form'); // autoupdate
let user = global.get('user'); // autoupdate
let admin = global.get('auth.admin') || {}; // read

// Get UI user structure
if (typeof msg.hmi !== 'object') {
    msg.hmi = { ...global.get('describe.template.hmi') }; // clone
}

// Get UI page
if (typeof msg.name === 'string') {
    msg.hmi.name = msg.name;
    delete msg.name;
}
delete msg.tab; //?

// Get UI user
if (typeof msg._client === 'object' && typeof msg._client.socketId === 'string') {
    // Get use lang
    const browser_lang = global.get('browser["' + msg._client.socketId + '"]["lang"]');
    if (typeof browser_lang === 'string') {
        msg.hmi.lang = browser_lang;
    }
    msg.hmi.id = msg._client.socketId;


    /* Bypass auth */
    //*
    if ((global.get('autologin', 'file') || false) === true && 
        (typeof user[msg.hmi.id] !== 'object' || user[msg.hmi.id]['login'] === '')
    ) {
        user[msg.hmi.id] = { ...admin };
        user[msg.hmi.id]['login'] = 'admin';

        delete user[msg.hmi.id]['pass'];
    }
    //*/

    if (typeof user[msg.hmi.id] === 'object') {
        user[msg.hmi.id]['time'] = Date.now();

        msg.hmi = {...msg.hmi, ...user[msg.hmi.id]};
    }

    if (typeof form[msg.hmi.id] !== 'object') {
        form[msg.hmi.id] = { };
    }
}

// Get lang dictionary
msg.dictionary = { ...(global.get('dictionary.en') || { }), ...(global.get('dictionary["' + msg.hmi.lang + '"]') || { }) };

return msg;

if (typeof msg.login === 'string' && msg.login !== "" && 
    typeof msg.pass === 'string' && msg.pass !== ""
) {
    msg.login = msg.login.toLowerCase();
    const hash = global.get('auth["' + msg.login + '"]["pass"]');
    if (typeof hash === 'string') {
        msg.hash = hash;

        node.send([msg, null]);

        return;
    }
}

node.send([null, msg]);

return;

// Get memories
let user = global.get('user'); // autoupdate

user[msg._client.socketId] = {
    'login': msg.login,
    'level': global.get('auth["' + msg.login + '"]["level"]') || '',
    'lang': global.get('auth["' + msg.login + '"]["lang"]' ) || '',
    'time': Date.now()
};

delete msg.login;
delete msg.pass;
delete msg.match;
delete msg.hash;

msg.payload = true;

return msg;

// Get memories
let user = global.get('user'); // autoupdate

delete user[msg._client.socketId];

delete msg.login;
delete msg.pass;
delete msg.match;
delete msg.hash;

msg.payload = false;

return msg;

// Get memories
let user = global.get('user'); // autoupdate
let form = global.get('form'); // autoupdate

/* Limit to 6 hours */
const limit = Date.now() - ( 6 * 60 * 60 * 1000);

for (const u in user) {
    if (typeof global.get('auth["' + user[u]["login"] + '"]["level"]') !== 'string' 
    || user[u]["time"] < limit 
    || (typeof msg.login === 'string' && msg.login === user[u]["login"])
    ) {
        delete user[u];
        delete form[u];

        msg.payload = u;
        node.send([msg]);
    }
}

msg.payload = 'cleaned';

return msg;

let has_admin = false;

if (typeof msg.payload === 'object') {
    for (const login in msg.payload) {
        if (typeof msg.payload[login]["pass"] === 'string'
            && typeof msg.payload[login]["pass"] === 'string'
            && typeof msg.payload[login]["level"] === 'string'
        ) {
            if (typeof msg.payload[login]["lang"] !== 'string') {
                msg.payload[login]["lang"] = 'fr';
            }
            if (typeof msg.payload[login]["telegram"] !== 'string') {
                msg.payload[login]["telegram"] = '';
            }

            if (msg.payload[login]["level"] === 'admin') {
                has_admin =  true;
            }

            global.set('auth["' + login + '"]',{
                'pass': msg.payload[login]["pass"],
                'level': msg.payload[login]["level"],
                'lang': msg.payload[login]["lang"],
                'telegram': msg.payload[login]["telegram"]
            });
        }
    }
}

if (!has_admin) {

    return msg;
}

return;

// If there are no users, set an default admin account
msg.payload = {
    'admin': {
        'pass': 'admin',
        'level': 'admin',
        'lang': 'fr',
        'telegram': ''
    }
};

return msg;

global.set('auth', msg.payload);

msg.payload = '';

return msg;

msg.payload = global.get('auth');
delete msg.filename;

return msg;

// Get memories
let form = global.get('form'); // autoupdate

const check = msg.check || '-';

if (msg.hmi.level !== ''
    && msg.hmi.name === global.get('describe.page["' + check + '"]["name"]')
    && global.get('describe.page["' + check + '"]["level"]["' + msg.hmi.level + '"]') === true
) {
    msg.class = '';
    msg.enabled = true;

    if (typeof form[msg.hmi.id][check] !== 'object') {
        form[msg.hmi.id][check] = { };
    }

    // Wait
    msg = await node.linkcall('common - wait', msg);
} else {
    msg.topic = '';
    msg.payload = '';
    msg.class = 'remove';
    msg.enabled = false;
    msg.title = '-';
}

delete msg.check;

return msg;

format:
.app-bar-actions-title {
    margin: auto;
    text-shadow: rgb(var(--v-theme-background)) 2px 2px 1px;
}

body {
    background-color: rgb(var(--v-theme-background)) !important;
}

.v-toolbar .v-btn-group {
    background: rgb(var(--v-theme-navigation-background));
}

.remove *,
.v-card .remove,
.v-card-text .remove,
.v-card-item {
    display: none !important;
    visibility: hidden;
    color: transparent !important;
}

.dknr-center {
    margin: auto;
}

.dknr-center .nrdb-switch,
.dknr-center .v-btn-group {
    margin: auto;
}

tbody td[data-column-key=dknr-label] {
    font-weight: bold !important;
}

.v-tab-item--selected {
    color: rgb(var(--v-theme-primary)) !important;
}

.nrdb-ui-group {
    border-radius: 4px;
}

.v-main {
    padding-bottom: 2em;
}

.dknr-title span {
    font-size: 1.4rem !important;
    font-weight: normal !important;
    padding: 0;
    margin-top: 0.5em;
    color: rgb(var(--v-theme-primary)) !important;
}
.dknr-row-icon {
    font-size: 1.8em;
}
.dknr-weather {
    font-family: Arial, Helvetica, sans-serif;
}
.dknr-weather-day th {
    display: none;
    visibility: hidden;
}
.dknr-weather-day td {
    border-bottom-width: 0 !important;
    border-left-width: 1px !important;
}
.dknr-weather-day span.dknr-weather {
    font-size: 1.4em;
}
.dknr-weather img {
    width: 4em;
    height: 4em;
    background-color: rgb(var(--v-theme-primary));
    border-radius: 4px;
}
.dknr-camera {
    text-align: center !important;
    flex: 1 0;
}
.dknr-camera img {
    width: 90%;
    border-radius: 4px;
    border: 1px solid rgba(var(--v-theme-group-outline));
}
.dknr-map {
    color: rgb(var(--v-theme-background));
    fill: rgb(var(--v-theme-primary));
}
.dknr-bg {
    fill: rgb(var(--v-theme-background));
}
.dknr-blue {
    fill: rgb(var(--v-theme-primary));
}
.dknr-green {
    fill: green;
}
.dknr-orange {
    fill: orange;
}
.dknr-red {
    fill: red;
}
.dknr-grey {
    fill: grey;
}
.dknr-light > .dknr-zone {
    fill: rgb(255, 225, 0, 0.1);
}
.dknr-motion > .dknr-title {
    stroke: red;
    stroke-opacity: 0.5;
}
.dknr-climate > .dknr-text {
    fill: red;
}
.dknr-aperture > .dknr-zone {
    stroke: red;
    stroke-width: 5px;
    stroke-opacity: 0.25;
}

func:
// Get memories
let user = global.get('user'); // autoupdate
let form = global.get('form'); // autoupdate
let pages = global.get('describe.page'); // read

// Get ui data
msg = await node.linkcall('common - ui - hmi', msg);

if (!['connect', 'lost', 'change'].includes(msg.payload)) {

    return;
}

if (msg.payload === 'lost') {

    delete user[msg.hmi.id];
    delete form[msg.hmi.id];

    return;
}

// On connect, go to auth page
if (msg.payload === 'connect') {
    // Bypass auth
    msg.payload = (global.get('autologin', 'file') || false) === true ? pages.home.name : pages.auth.name;
    msg.hmi.name = msg.payload;

    node.send([null, null, msg]);
}

// Prepare ui
msg.buttons = [];
msg.payload = {
    'pages': {
        'show': [],
        'hide': []
    }
};

// check user page right
let allowed = false;
let current = pages.auth.name;
for (const page in pages) {
    if (typeof pages[page]['level'][msg.hmi.level] === 'boolean' 
        && pages[page]['level'][msg.hmi.level] === true
        || pages.auth.name === pages[page]['name']
    ) {
        msg.buttons.push({
            'id': pages[page]['name'],
