msg.topic = msg.topic.slice(mqtt.topic.length + 1);
let path = msg.topic.split('/');
let action = path.shift();
msg.uid = path.join('/');

if (action === 'discovery') {
    // discovery source
    if (path.length === 1) {
        if (typeof msg.payload === 'string' && msg.payload === '') {
            // delete source[path[0]];
        }
        else if (typeof msg.payload === 'object') {
            if (typeof source[path[0]] !== 'object') {
                source[path[0]] = { ...template.source };
            }
            for (const k in template.source) {
                if (msg.payload.hasOwnProperty(k)) {
                    source[path[0]][k] = msg.payload[k];
                }
            }
        }
    }
    // discovery parent
    else if (path.length === 2) {
        if (typeof msg.payload === 'string' && msg.payload === '') {
            // delete parent[path[1]];
        }
        else if (typeof msg.payload === 'object' && (msg.payload.name || '') !== '' && typeof parent[path[1]] !== 'object') {
            parent[path[1]] = { ...template.parent, ...{ 'id': path[1], 'name': msg.payload.name.replace('_', ' ') } };
        }
    }
    // discovery entity
    else if (path.length === 3) {
        node.status({
            'fill': 'blue',
            'text': action + ': ' + msg.uid
        });

        if (typeof msg.payload === 'string' && msg.payload === '') {
            // delete discovery[uid];
        }
        else if (typeof msg.payload === 'object') {
            if (typeof discovery[msg.uid] !== 'object') {
                discovery[msg.uid] = { ...template.discovery };
            }
            for (const k in template.discovery) {
                if (msg.payload.hasOwnProperty(k)) {
                    if (typeof msg.payload[k] === 'object') {
                        discovery[msg.uid][k] = { ...msg.payload[k] };
                    }
                    else {
                        discovery[msg.uid][k] = msg.payload[k];
                    }
                }
            }

            // Create entity if it does not exist, or complete it from discovery
            if (block[msg.uid] !== true) {
                const exists = typeof entity[msg.uid] === 'object';
                const seen = exists ? entity[msg.uid]['seen'] : Date.now();

                msg = await node.linkcall('common - entity - merge', msg);

                // Discovery is not a value: keep last seen time of existing entity
                entity[msg.uid]['seen'] = seen;

                if (!exists) {
                    node.status({
                        'fill': 'green',
                        'text': 'new entity: ' + msg.uid
                    });
                }
            }
        }
    }
}
else if (action === 'get' && path.length === 3) {

    // Ignore blocked entity
    if (block[msg.uid] === true) {

        return;
    }

    // update entity
    msg = await node.linkcall('common - entity - merge', msg);

    // DKNR binary values are 1 / 0 (ON / OFF from older versions)
    let value = msg.payload;
    if (typeof discovery[msg.uid] === 'object' && discovery[msg.uid]['type'] === 'binary') {
        value = [true, 1, '1', 'ON', 'on', 'On', 'true'].includes(value) ? 1 : 0;
    }

    const old_value = entity[msg.uid]['value'];
    entity[msg.uid]['value'] = value;

    /* same info in next node
    node.status({
        'fill': old_value !== value ? 'green' : 'yellow',
        'text': action + ' : ' + msg.uid + ' : ' + value
    });
