    // Send entity event (even if value is unchanged, see msg.repeat)
    msg.topic = msg.uid;
    msg.payload = value;
    msg.repeat = entity[msg.uid]['element'] !== 'remote' && old_value === value;

    delete msg.qos;
    delete msg.retain;
