    };
    entity[uid]['unit'] = discovery[uid]['unit'] !== '' ? discovery[uid]['unit'] : (units[discovery[uid]['type']] || '');
}
if (create) {
    entity[uid]['value'] = discovery[uid]['type'] === 'binary' ? ([true, 1, '1', 'ON', 'on', 'On', 'true'].includes(discovery[uid]['value']) ? 1 : 0) : discovery[uid]['value'];
}

if (create && entity[uid]['name'] === '') {
    entity[uid]['name'] = discovery[uid]['name'];
}

for (const k in discovery[uid]['options']) {
    if (!entity[uid]['options'].hasOwnProperty(k) || entity[uid]['options'][k] === '') {
