const textuals = [ ...(global.get('describe.texts') || []) ];

// Get trigger values
let inputvalue = msg.trigger.value;
let inputhigh = msg.param.inputhigh;
let inputlow = msg.param.inputlow;
let is_num = textuals.includes(msg.trigger.unit) ? false : true;

// Need to convert time in num
if (msg.trigger.unit === 'time') {
    inputvalue = inputvalue.split(':').join('');
    inputhigh = Number(inputhigh.split(':').join(''));
    inputlow = Number(inputlow.split(':').join(''));
    is_num = true;
}

// Check if high and low levels are reverted
let is_rev = is_num && inputhigh < inputlow ? true : false;

// Prepare toggle value
let toggle = msg.target.value === msg.scene.off ? true : false;

// On high input
if (!is_num && inputvalue === inputhigh
 || is_num && !is_rev && Number(inputvalue) >= inputhigh
 || is_num && is_rev && Number(inputvalue) <= inputhigh
) {
    if (msg.param.outputhigh === 'high') {
