/*
cron (preroutine):
Ping scene target as trigger every minute to update levels and timers.
*/

node.status({ });

// Get used data
const now = Date.now();
const scenes = { ...(global.get('scene') || {}) };
const entities = { ...(global.get('entity') || {}) };
const template = { ...(global.get('describe.template') || {}) };
let total = 0;
let expired = 0;

// Loop through scenes targets
for (const e in scenes) {

    // Stop if target as no timer
    if (typeof entities[e] !== 'object') {

        continue;
    }

    const trigger = { ...template.entity, ...entities[e] };

    // Stop if we can not find target definition
    if (trigger.uid === '') {

        continue;
    }

    total++;

    // Clone data to msg
    let newMsg = {
        'topic': trigger.uid,
        'payload': trigger,
        //'replay': true
    };

    // If timer expired force trigger (as target) to off
    const limit = scenes[e].timer + (scenes[e].duration * 60 * 1000);
    if (scenes[e].timer > 0 && now > limit) {
        newMsg.payload.value = scenes[e].off;
        expired++;
    }
    else {
        continue;
    }

    node.send([newMsg]);
}

node.status({ 'fill': total ? 'green' : 'red', 'text': 'triggers ' + total +', ' + expired + ' expired' });

return;

