// Get usefull data
const entities = { ...(global.get('entity') || { }) };
const now = Date.now();
const current = {
    'indoor': 0,
    'outdoor': 0,
    'aperture': 0,
    'mode': 'off',
    'setpoint': 7,
    'calculation': -10000 // positive result to pilot
};


//
// Compute triggers
//

let temperature_outdoor_count = 0;
let temperature_indoor_count = 0;

for (const t in msg.scene.trigger) {
    // Trigger is already in used
    if (typeof entities[t] !== 'object' || entities[t]['hidden'] !== 0) {

        continue;
    }

    // Get temperatures
    if ([ 'temperature' ].includes(entities[t]['element']) && entities[t]['group'] === 'sensor') {
        // 0 is considered as wrong value.
        if (entities[t]['value'] === 0) {

            continue;
        }

        // Outdoor temperature
        if (global.get('room["base"]["' + entities[t]['room'] + '"]["outdoor"]') === 1) {
            temperature_outdoor_count++;
            current.outdoor = parseInt(current.outdoor + entities[t]['value'] * 10);
        }
        // Indoor temperature
        else {
            temperature_indoor_count++;
            current.indoor = parseInt(current.indoor + entities[t]['value'] * 10);
        }
    }

    // Get apertures states
    if ([ 'door', 'window', 'slider' ].includes(entities[t]['element'])) {
        if (entities[t]['value'] === 0) { // 0 = opened
            current.aperture = 1; // 1 = opened
        }
    }
}

// Temperature is required
if (temperature_indoor_count === 0 || temperature_outdoor_count === 0) {
    msg.rsp = false;
    msg.summary.thermostat = 'thermostat has no temperature sensors';
    node.status({
        'fill': 'red',
        'text': msg.summary.thermostat
    });

    return msg;
}

// Compute temperatures
current.indoor = Math.round(current.indoor / temperature_indoor_count) / 10;
current.outdoor = Math.round(current.outdoor / temperature_outdoor_count) / 10;

// Get thermostat mode
current.mode = global.get('entity["dknr/sensor/temperature"]["value"]') || 'off';


//
// Compute data
//

// Get requested temperature
switch (current.mode) {
    case 'off':
/*        msg.rsp = false;
        msg.summary.thermostat = 'thermostat mode is off';
        node.status({
            'fill': 'red',
            'text': msg.summary.thermostat
        });

        return msg;
*/
        break;
    case 'heating':
        let confort = false;
        // Get current time and day
        let time = Number((new Date().getHours().toString()) + (new Date().getMinutes().toString().padStart(2, '0')));
        let today = 'd' + (new Date().getDay());
        // Get room workdays and confort hours
        let workdays = { ...{ 'd0':0, 'd1':0, 'd2':0, 'd3':0, 'd4':0, 'd5':0, 'd6':0 }, ...(global.get('room["workday"]["' + msg.target.room + '"]') || { }) };
        let conforts = [ ...(global.get('room["confort"]["' + msg.target.room + '"]') || [ ]) ];
        for (let c = 0; c < conforts.length; c++) {
            // current day is same as time plot
            if (confort === false && (!!workdays[today]) === conforts[c]['workday']) {
                let start = Number(conforts[c]['start'].split(':').join(''));
                let stop = Number(conforts[c]['stop'].split(':').join(''));

                // Time is between two days
                if (start > stop) {
                    if (start < time || time < stop) {
                        confort = true;
                    }
                }
                else {
                    // If current time is in confort hours
                    if (start < time && time < stop) {
                        confort = true;
                    }
                }
            }
        }
        current.time = time; // debug
        current.confort = confort; // debug
        current.setpoint = confort ? msg.scene.temperature_setpoint_confort : current.setpoint = msg.scene.temperature_setpoint_eco;
        break;
    case 'cooling':
        current.setpoint = msg.scene.temperature_setpoint_cold;
        break;
    case 'thawing':
        current.setpoint = 7;
        break;
    default:
        msg.rsp = false;
        msg.summary.thermostat = 'thermostat has no temperautre setpoint';
        node.status({
            'fill': 'red',
            'text': msg.summary.thermostat
        });

        return msg;
}

// Compute cold request
if (current.mode === 'cooling') {
    // Cold temperature is set to 18° means cooling is disabled
    if (current.setpoint > 18) {
        current.calculation = ((current.indoor - current.setpoint) * msg.scene.temperature_coefficient_indoor) + ((current.outdoor - current.indoor) * msg.scene.temperature_coefficient_outdoor);
    }
}
// Compute heat request
else {
    current.calculation = ((current.setpoint - current.indoor) * msg.scene.temperature_coefficient_indoor) + ((current.indoor - current.outdoor) * msg.scene.temperature_coefficient_outdoor);
}

// Final compute heat/cold request
let calculb = (current.calculation / 100 * msg.scene.temperature_duration_cycle);
let calculc = (msg.scene.temperature_duration_cycle * msg.scene.temperature_duration_preheat / 100);
current.calculation = Number(calculb.toFixed(1)) - Number(calculc.toFixed(1));

// Aperture state changes, set a timer
if (current.aperture !== msg.scene.temperature_aperture_opened) {
    msg.scene.temperature_aperture_opened = current.aperture;
    msg.scene.temperature_aperture_timer = now;
}

// Aperture timer is perempted, update it and go on
if (msg.scene.temperature_aperture_timer > 0 && (msg.scene.temperature_aperture_timer + msg.scene.temperature_duration_aperture * 60000) < now) {
    msg.scene.temperature_aperture_timer = 0;
}

// State
if (current.mode === 'off') {
    msg.scene.temperature_pilot_state = 'stopped';
}
else if (msg.scene.temperature_aperture_timer > 0) {
    msg.scene.temperature_pilot_state = 'suspended';
}
else if (msg.scene.temperature_aperture_opened === 1) {
    msg.scene.temperature_pilot_state = 'stopped';
}
else if (current.mode === 'cooling' && msg.scene.temperature_energy_free === 1) {
    // Find solar power entity
    const solar_entity = global.get('energy["solar_power"]') || '';
    if (solar_entity !== ''
        && typeof entities[solar_entity] === 'object'
        && entities[solar_entity]['hidden'] === 0
    ) {
        // If not enought solar power, stop
        if (entities[solar_entity]['value'] < msg.scene.temperature_power_consumption) {
            msg.scene.temperature_pilot_state = 'stopped';
        }
    }
}
else if (current.calculation > 0) {
    msg.scene.temperature_pilot_state = 'powered';
}
else if ((now - msg.scene.temperature_duration_cycle * 60000) > msg.scene.temperature_pilot_last) {
    msg.scene.temperature_pilot_state = 'reached';
}
else {
    // unchanged
}

// Pilot final order
if ([ 'powered' ] .includes(msg.scene.temperature_pilot_state)) {
