Output 1: entity event, output 2: MQTT command
*/

if (global.get('stop') === true || global.get('boot') === true) {

    return;
}

if (typeof msg.payload !== 'object' || typeof msg.payload.uid !== 'string') {

    return;
}

// Get memories
let entity = global.get('entity'); // autoupdate

const uid = msg.payload.uid;
if (typeof entity[uid] !== 'object') {
    node.status({ 'fill': 'red', 'text': 'unknown ' + uid });

    return;
}

let value = msg.payload.value;

// Always convert boolean to int
if (typeof value === 'boolean') {
    value = value ? 1 : 0;
}
// Binary values are 0 or 1
if (['b', 'rb'].includes(entity[uid]['unit'])) {
    value = value === 0 || value === '0' ? 0 : 1;
}

const old_value = entity[uid]['value'];

// Only commands can be sent
if (entity[uid]['group'] !== 'command') {
    node.status({ 'fill': 'red', 'text': 'not a command ' + uid });

    return;
}

node.send([null, { 'topic': uid, 'payload': value }]);

// Update entity
entity[uid]['value'] = value;
entity[uid]['seen'] = Date.now();

node.status({ 'fill': old_value === value ? 'blue' : 'green', 'shape': 'ring', 'text': uid + ' : ' + value });

return [{
    'topic': uid,
    'payload': value,
    'repeat': entity[uid]['element'] !== 'remote' && old_value === value
}, null];

