msg.topic is the entity uid.
*/

// Get dknr data
msg = await node.linkcall('common - dknr - data', msg);

const path = msg.topic.split('/');
const def = (msg.dknr_entity.command || {})[path[2]];
const enums = msg.dknr_enum[path[2]] || {};

delete msg.dknr_enum;
delete msg.dknr_entity;

if (path[1] !== 'command' || !Array.isArray(def)) {
    node.status({ 'fill': 'red', 'text': 'unknown ' + msg.topic });

    return;
}

let value = msg.payload;
if (typeof value === 'number') {
    value = value.toString();
}

// Check value
if (typeof value !== 'string'
    || def[1] === 'enum' && !enums.hasOwnProperty(value)
    || def[1] === 'time' && !/^\d{2}:\d{2}$/.test(value)
) {
    node.status({ 'fill': 'red', 'text': 'bad value ' + msg.topic + ' : ' + value });

    return;
}

node.status({ 'fill': 'green', 'text': msg.topic + ' : ' + value });

return {
    'topic': '',
    'payload': {
        'parent': 'command',
        'id': path[2],
        'value': value
    },
    'compute': true
};

/*
Update a DKNR local value and publish it on <topic>/get/dknr/<parent>/<id>.
msg.payload: { parent, id, value }
Output 1: MQTT, output 2: compute sensors after a command
*/

// Get dknr data
msg = await node.linkcall('common - dknr - data', msg);
const defs = msg.dknr_entity;
delete msg.dknr_enum;
delete msg.dknr_entity;

const p = msg.payload.parent;
const id = msg.payload.id;
if (typeof defs[p] !== 'object' || !Array.isArray(defs[p][id])) {
    node.status({ 'fill': 'red', 'text': 'unknown ' + p + '/' + id });

    return;
}

// Get memories
let state = global.get('dknr'); // autoupdate
if (typeof state[p] !== 'object') {
    state[p] = {};
}

const compute = msg.compute === true ? { 'topic': '', 'payload': '' } : null;

// Publish only changes
if (state[p][id] === msg.payload.value) {
    node.status({ 'fill': 'blue', 'text': p + '/' + id + ' : ' + msg.payload.value });

    return [null, compute];
}

state[p][id] = msg.payload.value;
node.status({ 'fill': 'green', 'text': p + '/' + id + ' : ' + msg.payload.value });

const mqtt = global.get('mqtt') || {};
if (!mqtt.enabled || (mqtt.topic || '') === '') {

    return [null, compute];
}

return [{
    'topic': [mqtt.topic, 'get', 'dknr', p, id].join('/'),
    'payload': msg.payload.value,
    'qos': 0,
    'retain': true
}, compute];

/*
Publish DKNR local source like other DKNR sources:
discovery of source, parents and entities, then all values (retained).
*/

const mqtt = global.get('mqtt') || {};
if (!mqtt.enabled || (mqtt.topic || '') === '') {

    return;
}

// Get dknr data
msg = await node.linkcall('common - dknr - data', msg);
const defs = msg.dknr_entity;
const enums = msg.dknr_enum;

// Get memories
let state = global.get('dknr'); // autoupdate
const entity = global.get('entity') || {}; // read
const app = global.get('describe.app') || {}; // read

const topic = mqtt.topic;
const source = 'dknr';
const parents = {
    'sensor': 'Configuration',
    'command': 'Domotic'
};
const pub = (t, p) => node.send({ 'topic': t, 'payload': p, 'qos': 0, 'retain': true });

// Source
pub([topic, 'discovery', source].join('/'), {
    'title': 'Domotic',
    'version': app.version || '',
    'git': '',
    'mdi': 'eye'
});

let i = 0;
for (const p in defs) {
    if (typeof state[p] !== 'object') {
        state[p] = {};
    }

    // Parent
    pub([topic, 'discovery', source, p].join('/'), { 'name': parents[p] || p });

    for (const id in defs[p]) {
        const def = defs[p][id];

        // Default value, or value of an existing entity (previous version)
        if (typeof state[p][id] === 'undefined') {
            const old = entity[[source, p, id].join('/')];
            state[p][id] = typeof old === 'object' && old.value !== '' ? old.value : def[0];
        }

        // DKNR type and unit
        let type = 'number';
        let unit = def[1];
        let options = {};
        if (def[1] === 'enum') {
            type = 'enum';
            unit = '';
            for (const k in (enums[id] || {})) {
                options[k] = enums[id][k][1];
            }
        }
        else if (['time', 'text'].includes(def[1])) {
            type = 'text';
            unit = def[1] === 'time' ? 'time' : '';
        }

        pub([topic, 'discovery', source, p, id].join('/'), {
            'name': def[3],
            'group': p,
            'type': type,
            'unit': unit,
            'value': def[0],
            'options': options
        });

        pub([topic, 'get', source, p, id].join('/'), state[p][id]);
        i++;
    }
}

node.status({ 'fill': 'green', 'text': i + ' entities' });

return;

