const now = new Date();

function cleanCalendar(entry, long) {
    let res = { ...entry };

    // Set readble date
    let date = new Date(res['ts']);
    res['fulldate'] = date.toLocaleDateString(msg.dictionary.common.locales) + (long ? ' ' + res['time'] : '');

    // Convert date to current year date
    date.setFullYear(now.getFullYear());
    if (date < now) {
        date.setFullYear(now.getFullYear() + 1);
    }
    res['thisyear'] = date.getTime();

    // Compute icon
    let icon = icons[res['type']][1];
    let color = colors.empty;
    if ((now.getTime() - 86400000) < date.getTime() && (now.getTime() + 86400000) > date.getTime()) {
        icon = icons[res['type']][1];
        color = colors.theme;
    }
    res['icon'] = '<i class="dknr-row-icon mdi mdi-' + icon + '" style="color:' + color + '" title="' + res['type'] + '"></i>';

    return res;
}

