            name = typeof parent[entity['parent']] === 'object' ? parent[entity['parent']]['name'] : '';
            if (name === '') {
                name = entity['parent'];
            }
        }

        let option = '';
        for (const o in options) {
            if (template[entity['element']].includes(o) && scene[e][o] > 0) {
                let option_icon = options[o][1];
                let option_color = colors.none;
                let option_name = msg.dictionary.option_scene[o] || o;
                option += '<i class="dknr-row-icon mdi mdi-' + option_icon + '" style="color:' + option_color + '" title="' + option_name + '"></i>';
            }
