            'scene_icon': '<i class="dknr-row-icon mdi mdi-' + icon + '" style="color:' + color + '" title="' + ticon[2] + '"></i>',
            'target': e,
            'value': entity.value,
            'name': name,
            'option': '<span style="white-space: nowrap;">' + option + '</span>',
            'enabled': enabled
        };
