// Get history of last 24 hours

const textuals = [ ...(global.get('describe.texts') || []) ];
const binary = ['b', 'rb'].includes(msg.payload.unit);
const numeric = !binary && !textuals.includes(msg.payload.unit);

// Numbers are averaged every 5 minutes, other values keep their changes
msg.query =
'from(bucket: "domotic")' +
'|> range(start: -1d, stop: now())' +
'|> filter(fn: (r) => r["_field"] == "' + msg.payload.uid + '")' +
(numeric ? '|> aggregateWindow(every: 5m, fn: mean, createEmpty: false)' : '|> aggregateWindow(every: 1m, fn: last, createEmpty: false)') +
'|> yield(name: "history")';

// Reset chart while loading
node.send([null, {
    'topic': msg.topic,
    'payload': {
        'kind': 'loading',
        'texts': { 'loading': msg.dictionary.room.history_loading || 'Loading…' }
    }
}]);

msg.payload = [];

return [msg, null];

// Prepare last 24 hours history for chart

const entity = global.get('entity["' + msg.topic + '"]') || {};
const textuals = [ ...(global.get('describe.texts') || []) ];
const reverts = [ ...(global.get('describe.reverts') || []) ];
const dict = msg.dictionary.room || {};

const end = Date.now();
const start = end - 24 * 3600000;
const rows = (Array.isArray(msg.payload) ? msg.payload : [])
    .map(r => [new Date(r._time).getTime(), r._value])
    .filter(r => !isNaN(r[0]) && r[1] !== null && r[1] !== undefined)
    .sort((a, b) => a[0] - b[0]);

let res = {
    'kind': 'empty',
    'unit': entity.unit || '',
    'locale': msg.dictionary.common.locales || 'fr',
    'start': start,
    'end': end,
    'points': [],
    'current': entity.value,
    'texts': {
        'empty': dict.history_empty || 'No history for the last 24 hours',
        'now': dict.history_now || 'Now',
        'min': dict.history_min || 'Minimum',
        'max': dict.history_max || 'Maximum'
    }
};

if (rows.length > 0 && ['b', 'rb'].includes(entity.unit)) {
    // Binary: 1 means active (on, opened...)
    const revert = (entity.unit === 'rb') !== (reverts.includes(entity.element));
    const active = v => (Number(v) ? 1 : 0) ^ (revert ? 1 : 0);
    const aperture = ['aperture', 'door', 'window', 'lock', 'shutter', 'slider'].includes(entity.element);

    res.kind = 'binary';
    res.points = rows.map(r => [r[0], active(r[1])]);
    res.current = active(entity.value);
    res.texts.on = aperture ? (dict.open || 'Opened') : (dict.on || 'On');
    res.texts.off = aperture ? (dict.close || 'Closed') : (dict.off || 'Off');
}
else if (rows.length > 0 && !textuals.includes(entity.unit)) {
    // Number
    res.kind = 'line';
    res.points = rows.map(r => [r[0], Number(r[1])]).filter(r => !isNaN(r[1]));
    res.current = Number(entity.value);
    if (entity.unit === '8b') {
        // 8 bits value as percent
        res.points = res.points.map(r => [r[0], Math.round(r[1] * 100 / 255)]);
        res.current = Math.round(res.current * 100 / 255);
        res.unit = '%';
    }
}
else if (rows.length > 0) {
    // Text and enum: last changes, newest first
    const options = entity.options || {};
    const enums = global.get('describe["enum"]["' + entity.source + '"]["' + entity.id + '"]') || {};
    const label = v => Array.isArray(enums[v]) ? enums[v][1] : (options[v] || v);
    let changes = [];
    for (const r of rows) {
        if (changes.length === 0 || changes[changes.length - 1][1] !== label(r[1])) {
            changes.push([r[0], label(r[1])]);
        }
    }
    res.kind = 'list';
    res.points = changes.reverse().slice(0, 12);
}

if (res.points.length === 0) {
    res.kind = 'empty';
}

msg.payload = res;

return msg;

